local VERSION='10.0.0'
local commandCosts, qualityAdjustments, integrity = {}, {}, {}
local function uid(p)return('%s-%s-%04d'):format(p,os.time(),math.random(0,9999))end
exports('CreateCriticalEpisodeCostV10',function(patientCid,episodeId,resources)local total=0;local byCategory={};for _,row in ipairs(resources or{})do local amount=tonumber(row.cost)or 0;total=total+amount;local category=tostring(row.category or'other');byCategory[category]=(byCategory[category]or 0)+amount end;local item={id=uid('COST10'),patientCid=patientCid,episodeId=episodeId,total=math.floor(total*100)/100,byCategory=byCategory,createdAt=os.time()};commandCosts[item.id]=item;return true,item end)
exports('ApplyQualityAdjustmentV10',function(episodeId,metrics)local adjustment=0;if metrics and tonumber(metrics.closedLoopCompliance)and metrics.closedLoopCompliance<70 then adjustment=adjustment-5 end;if metrics and tonumber(metrics.preventableDelayMinutes)and metrics.preventableDelayMinutes>15 then adjustment=adjustment-8 end;local item={id=uid('QA10'),episodeId=episodeId,adjustmentPercent=adjustment,metrics=metrics or{},createdAt=os.time()};qualityAdjustments[item.id]=item;return item end)
exports('ValidateRevenueIntegrityV10',function(claim)local issues={};for _,key in ipairs({'patientCid','episodeId','diagnoses','procedures','provider','medicalNecessity'})do if not claim or claim[key]==nil then issues[#issues+1]=key end end;local item={id=uid('RI10'),valid=#issues==0,issues=issues,score=math.max(0,100-#issues*15),createdAt=os.time()};integrity[item.id]=item;return item.valid,item end)
exports('GetV10BillingBoard',function()return{version=VERSION,commandCosts=commandCosts,qualityAdjustments=qualityAdjustments,integrity=integrity,generatedAt=os.time()}end)
CreateThread(function()Wait(8700);print('[dpn-medical-billing-plus] v10 critical episode costing and quality-linked integrity active')end)
